package android.graphics.drawable; import android.graphics.*; import android.content.res.*; public class StateListDrawable extends DrawableContainer { private int[][] states=new int[0][]; public void addState(int[] s,Drawable d){int[][] n=new int[states.length+1][];for(int i=0;i<states.length;i++)n[i]=states[i];n[states.length]=s;states=n;add(d);onStateChange(getState());} public boolean isStateful(){return true;} protected boolean onStateChange(int[] state){for(int i=0;i<states.length;i++){boolean match=true;for(int req:states[i]){boolean found=false;for(int x:state)if(x==Math.abs(req))found=true;if((req>0)!=found){match=false;break;}}if(match){boolean changed=current!=i;selectDrawable(i);children[i].setState(state);return changed;}}return false;} }